SELECT COUNT(*) FROM TB_ITEM i INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID WHERE i.STATUS NOT IN ('COMPLETED', 'DELETED')
AND i.STATUS = #{request.status}
AND i.DUE_DATE IS NOT NULL AND i.DUE_DATE < CURDATE()


WHERE i.TRANSFERRED_FROM IS NOT NULL
  AND i.BOARD_ID = #{boardId}
ORDER BY i.TRANSFERRED_AT DESC

SELECT i.ITEM_ID, i.BOARD_ID, i.GROUP_ID, i.CATEGORY_ID, i.CONTENT AS TITLE, i.CONTENT, i.DESCRIPTION, i.STATUS, i.PRIORITY, i.ASSIGNEE_USERNAME, i.REQUEST_DATE, i.DUE_DATE, i.PREVIOUS_STATUS, i.COMPLETED_BY, i.DELETED_AT, i.DELETED_BY, i.TRANSFERRED_FROM, i.TRANSFERRED_AT, i.CREATED_AT, i.CREATED_BY, i.UPDATED_AT, i.UPDATED_BY, b.BOARD_NAME, g.GROUP_NAME, g.GROUP_COLOR, cat.CATEGORY_NAME, cat.CATEGORY_COLOR, ua.NAME AS ASSIGNEE_NAME, uc.NAME AS CREATED_BY_NAME, uu.NAME AS UPDATED_BY_NAME, (SELECT COUNT(*) FROM TB_COMMENT c WHERE c.ITEM_ID = i.ITEM_ID) AS COMMENT_COUNT, /* 이관 정보 */ tb_orig.OWNER_USERNAME AS TRANSFERRED_BY_USERNAME, ut.NAME AS TRANSFERRED_BY_USER_NAME, /* 공유 정보 */ TRUE AS IS_SHARED_TO_ME, ish.CREATED_BY AS SHARED_BY_USERNAME, us.NAME AS SHARED_BY_USER_NAME FROM TB_ITEM i INNER JOIN TB_ITEM_SHARE ish ON i.ITEM_ID = ish.ITEM_ID AND ish.USERNAME = #{username} AND ish.DELETED_AT IS NULL INNER JOIN TB_BOARD b ON i.BOARD_ID = b.BOARD_ID LEFT JOIN TB_GROUP g ON i.GROUP_ID = g.GROUP_ID LEFT JOIN TB_CATEGORY cat ON i.CATEGORY_ID = cat.CATEGORY_ID LEFT JOIN TB_USER ua ON i.ASSIGNEE_USERNAME = ua.USERNAME LEFT JOIN TB_USER uc ON i.CREATED_BY = uc.USERNAME LEFT JOIN TB_USER uu ON i.UPDATED_BY = uu.USERNAME LEFT JOIN TB_BOARD tb_orig ON i.TRANSFERRED_FROM = tb_orig.BOARD_ID LEFT JOIN TB_USER ut ON tb_orig.OWNER_USERNAME = ut.USERNAME LEFT JOIN TB_USER us ON ish.CREATED_BY = us.USERNAME WHERE i.STATUS NOT IN ('DELETED')
AND i.CONTENT LIKE CONCAT('%', #{request.keyword}, '%')
AND i.STATUS = #{request.status}
AND i.PRIORITY = #{request.priority}
AND i.STATUS != 'COMPLETED'
ORDER BY ish.CREATED_AT DESC
LIMIT #{request.size} OFFSET #{request.offset}

